const stationRowsFromChargers = (chargers: Charger[]) => {
  const grouped = new Map<string, Charger[]>();
  chargers.forEach(charger => {
    const key = charger.stationName || charger.stationId;
    grouped.set(key, [...(grouped.get(key) ?? []), charger]);
  });
  return [...grouped.entries()].map(([name, stationChargers], index) => {
    const first = stationChargers[0];
    const online = stationChargers.some(charger => ['AVAILABLE','ONLINE','CHARGING'].includes(charger.status));
    const power = stationChargers.reduce((total, charger) => total + Number(charger.powerKw ?? 0), 0);
    return { name, city: [first.city, first.address].filter(Boolean).join(' · ') || `${first.vendor} ${first.model}`, chargers: stationChargers.length, power: `${power || first.powerKw || 0} kW`, status: online ? 'Online' : first.status, usage: 35 + (index * 13) % 55 };
  });
};

